/**
 * A month grid for choosing a date (`design/components/calendar.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/calendar.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import * as zag from '@zag-js/date-picker'
import { normalizeProps } from '@zag-js/solid'

import {
  Each,
  Keyed,
  agentDate,
  agentMember,
  claimSlot,
  createCell,
  createDerived,
  elementRef,
  mergeParts,
  scope,
  useDirection,
  useMachine,
  watchEffect,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/controls/calendar.module.css'
import Button from './Button'

export type FirstDayOfWeek = NonNullable<CalendarProps['firstDayOfWeek']>

export type CalendarDate = zag.CalendarDate

export interface CalendarMessages {
  previousMonth: string
  nextMonth: string
}

export interface CalendarProps {
  /**
   * Names the calendar from outside, as DatePicker's popup does.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  defaultValue?: CalendarDate | null
  /**
   * Disables the whole grid.
   */
  disabled?: boolean
  /**
   * Overrides the locale's first day of the week.
   */
  firstDayOfWeek?: 0 | 1 | 2 | 3 | 4 | 5 | 6
  /**
   * Controlled month navigation, for apps that need it.
   */
  focusedValue?: CalendarDate
  /**
   * App policy, such as booked-out days. Unavailable is not the same as disabled.
   */
  isDateUnavailable?: (date: CalendarDate) => boolean
  /**
   * Drives names, numbering and the week's first day. Defaults to the app's.
   */
  locale?: string
  maxValue?: CalendarDate
  /**
   * Defaults to generic English. Localized hosts pass strings from their catalog.
   */
  messages?: CalendarMessages
  minValue?: CalendarDate
  onChange?: (value: CalendarDate | null) => void
  onFocusChange?: (date: CalendarDate) => void
  value?: CalendarDate | null
}

/** A month grid for choosing a date. */
export default function Calendar(given: CalendarProps): JSX.Element {
  const props = mergeProps(
    { disabled: false } as Defaults<CalendarProps, 'disabled'>,
    claimSlot(given),
  )
  return scope(() => {
    const uid = createUniqueId()
    const root = elementRef<HTMLElement>()
    const browserLanguage = createCell(undefined as string | undefined)
    const travel = createCell('next')
    const shownMonth = createCell('')
    const monthButton = createCell(false)
    const say = createDerived(
      () => props.messages ?? { previousMonth: 'Previous month', nextMonth: 'Next month' },
    )
    const language = createDerived(() => props.locale ?? browserLanguage.value ?? 'en-US')
    const english = createDerived(() => language.value.toLowerCase().startsWith('en'))
    const zone = createDerived(() => Intl.DateTimeFormat().resolvedOptions().timeZone)
    const dayName = createDerived(
      () => (date: zag.DateValue, text: string, today: boolean, selected: boolean) => {
        if (!english.value) return text
        const said = today
          ? selected
            ? `Today, ${text} selected`
            : `Today, ${text}`
          : selected
            ? `${text} selected`
            : text
        if (props.minValue !== undefined && date.compare(props.minValue) === 0)
          return `${said}, First available date`
        if (props.maxValue !== undefined && date.compare(props.maxValue) === 0)
          return `${said}, Last available date`
        return said
      },
    )
    const documentDirection = useDirection()
    const service = useMachine(
      zag.machine,
      () =>
        ({
          id: uid,
          dir: documentDirection(),
          inline: true,
          locale: language.value,
          timeZone: zone.value,
          value: props.value === undefined ? undefined : props.value === null ? [] : [props.value],
          defaultValue: props.defaultValue == null ? undefined : [props.defaultValue],
          min: props.minValue,
          max: props.maxValue,
          focusedValue: props.focusedValue,
          startOfWeek: props.firstDayOfWeek,
          disabled: props.disabled,
          isDateUnavailable:
            props.isDateUnavailable === undefined
              ? undefined
              : (date) => props.isDateUnavailable?.(date as zag.CalendarDate) === true,
          onValueChange: (details) => {
            props.onChange?.((details.value[0] as zag.CalendarDate | undefined) ?? null)
          },
          onFocusChange: (details) => {
            props.onFocusChange?.(details.focusedValue as zag.CalendarDate)
          },
          onVisibleRangeChange: (details) => {
            void ((travel.value =
              shownMonth.value !== '' && details.visibleRange.start.toString() < shownMonth.value
                ? 'previous'
                : 'next'),
            (shownMonth.value = details.visibleRange.start.toString()))
          },
        }) as Partial<zag.Props>,
    )
    const api = createDerived(() => zag.connect(service, normalizeProps))
    const named = createDerived(() =>
      [props['aria-label'], api.value.visibleRangeText.formatted].filter(Boolean).join(', '),
    )
    const monthButtonsOff = createDerived(
      () =>
        `${api.value.getPrevTriggerProps().disabled === true} ${api.value.getNextTriggerProps().disabled === true}`,
    )
    const dayOf = createDerived(() => (date: zag.DateValue) => {
      const cell = api.value.getDayTableCellState({ value: date })
      const off = props.disabled || cell.invalid
      const refused = props.isDateUnavailable?.(date as zag.CalendarDate) === true
      const selected = cell.selected && !off && !refused
      return {
        date,
        cell,
        off,
        unavailable: refused,
        outside: cell.outsideRange,
        selectable: !off && !refused,
        selected,
        name: dayName.value(date, cell.valueText, cell.today, selected),
      }
    })
    const weeks = createDerived(() =>
      api.value.weeks.map((week) => week.map((date) => dayOf.value(date))),
    )
    const effect1 = () => {
      browserLanguage.value = globalThis.navigator?.language
    }
    onMount(effect1)
    const effect2 = () => {
      shownMonth.value = api.value.visibleRange.start.toString()
    }
    onMount(effect2)
    const effect3 = () => {
      void (
        monthButton.value &&
        ((held) =>
          held === null || held === document.body || (held as HTMLButtonElement).disabled === true)(
          document.activeElement,
        ) &&
        ((monthButton.value = false),
        requestAnimationFrame(() =>
          root.value
            ?.querySelector<HTMLElement>('[data-calendar-part="day"][tabindex="0"]')
            ?.focus(),
        ))
      )
    }
    watchEffect(
      createMemo(() => monthButtonsOff.value),
      effect3,
      false,
    )
    let release4: (() => void) | undefined
    const effect4 = () => {
      release4?.()
      const ran = agentMember({
        member: 'Calendar',
        element: () => root.value,
        state: () => ({ value: api.value.value[0]?.toString() ?? '', disabled: props.disabled }),
        actions: {
          set: {
            argument: 'text',
            run: (value) =>
              (() => {
                const date = agentDate(value, {
                  min: props.minValue,
                  max: props.maxValue,
                  unavailable: props.isDateUnavailable,
                })
                api.value.setValue([date])
                api.value.setFocusedValue(date)
              })(),
          },
        },
        withholds: () => root.value,
      })
      release4 = () => {
        ran()
      }
    }
    onMount(effect4)
    onCleanup(() => release4?.())
    return (
      <div
        {...mergeParts(api.value.getContentProps(), {
          class: styles.root,
          hidden: undefined,
          tabindex: undefined,
          'data-state': undefined,
          role: 'application',
          'aria-label': named.value,
          'aria-labelledby': props['aria-labelledby'],
          'data-member': 'calendar',
        })}
        ref={root.attach}
      >
        {/* header */}
        <div
          class={styles.header}
          onfocusin={() => (monthButton.value = true)}
          onfocusout={($event: FocusEvent) =>
            (monthButton.value = ($event.target as HTMLButtonElement).disabled === true)
          }
        >
          <Button
            variant="ghost"
            tone="neutral"
            size="sm"
            iconOnly={true}
            icon="previous"
            label={say.value.previousMonth}
            disabled={api.value.getPrevTriggerProps().disabled === true}
            onClick={() => api.value.goToPrev()}
          />
          {/* title */}
          <span class={styles.title} aria-live="polite">
            {api.value.visibleRangeText.formatted}
          </span>
          <Button
            variant="ghost"
            tone="neutral"
            size="sm"
            iconOnly={true}
            icon="next"
            label={say.value.nextMonth}
            disabled={api.value.getNextTriggerProps().disabled === true}
            onClick={() => api.value.goToNext()}
          />
        </div>
        {/* grid */}
        <Keyed by={api.value.visibleRange.start.toString()}>
          {() => (
            <table
              {...mergeParts(api.value.getTableProps(), {
                class: styles.grid,
                tabindex: undefined,
                'aria-label': named.value,
                'data-travel': travel.value,
              })}
            >
              <thead aria-hidden="true">
                <tr>
                  <Each of={api.value.weekDays} by={(weekday) => weekday.long} renew>
                    {(weekday) => (
                      <th scope="col" aria-label={weekday.long}>
                        <span aria-hidden="true">{weekday.short}</span>
                      </th>
                    )}
                  </Each>
                </tr>
              </thead>
              <tbody>
                <Each of={weeks.value} by={(_week, at) => at} renew>
                  {(week) => (
                    <tr>
                      <Each of={week} by={(day) => day.date.toString()} renew>
                        {(day) => (
                          <>
                            {day.outside ? (
                              <td />
                            ) : (
                              <td
                                class={styles.cell}
                                role="gridcell"
                                aria-disabled={!day.selectable ? 'true' : undefined}
                                aria-selected={day.selected ? 'true' : undefined}
                              >
                                {/* day */}
                                <div
                                  {...mergeParts(
                                    api.value.getDayTableCellTriggerProps({ value: day.date }),
                                    {
                                      class: styles.day,
                                      'data-calendar-part': 'day',
                                      'aria-label': day.name,
                                      'aria-current': day.cell.today ? 'date' : undefined,
                                      tabindex: day.off ? undefined : day.cell.focused ? 0 : -1,
                                      'data-selected': day.selected ? '' : undefined,
                                      'data-today': day.cell.today ? '' : undefined,
                                      'data-unavailable': day.unavailable ? '' : undefined,
                                      'data-disabled': day.off ? '' : undefined,
                                      onfocus: () => api.value.setFocusedValue(day.date),
                                      onkeydown: ($event: KeyboardEvent) =>
                                        $event.key === ' ' &&
                                        day.selectable &&
                                        ($event.preventDefault(), api.value.setValue([day.date])),
                                    },
                                  )}
                                >
                                  {day.date.day}
                                </div>
                              </td>
                            )}
                          </>
                        )}
                      </Each>
                    </tr>
                  )}
                </Each>
              </tbody>
            </table>
          )}
        </Keyed>
      </div>
    )
  })
}
